const source = $json;
const message = source.messages?.[0] ?? source.entry?.[0]?.changes?.[0]?.value?.messages?.[0] ?? null;
const status = source.statuses?.[0] ?? source.entry?.[0]?.changes?.[0]?.value?.statuses?.[0] ?? null;
const contacts = source.contacts ?? source.entry?.[0]?.changes?.[0]?.value?.contacts ?? [];
const metadata = source.metadata ?? source.entry?.[0]?.changes?.[0]?.value?.metadata ?? {};
const messageType = message?.type ?? 'status';
const media = message?.audio ?? message?.image ?? message?.document ?? message?.video ?? null;
return { json: {
  schema_version: '1.0',
  event_kind: message ? 'message' : status ? 'status' : 'unsupported_event',
  event_id: message?.id ?? status?.id ?? ('wa-' + $execution.id),
  occurred_at: message?.timestamp ? new Date(Number(message.timestamp) * 1000).toISOString() : new Date().toISOString(),
  from: message?.from ?? status?.recipient_id ?? '',
  customer_name: contacts[0]?.profile?.name ?? '',
  phone_number_id: metadata.phone_number_id ?? '',
  message_type: messageType,
  text: message?.text?.body ?? message?.button?.text ?? message?.interactive?.button_reply?.title ?? message?.interactive?.list_reply?.title ?? message?.image?.caption ?? message?.document?.caption ?? '',
  media_id: media?.id ?? '',
  media_mime_type: media?.mime_type ?? '',
  media_filename: message?.document?.filename ?? '',
  reply_to: message?.context?.id ?? '',
  status: status?.status ?? '',
  raw: source
} };

const n = $json;
const payload = {
  schema_version: '1.0', event_id: n.event_id, occurred_at: n.occurred_at, channel: 'whatsapp',
  contact: { wa_id: n.from, name: n.customer_name },
  message: { external_id: n.event_id, type: n.message_type, text: n.text, reply_to: n.reply_to || null,
    attachment: n.media_id ? { external_id: n.media_id, mime_type: n.media_mime_type || null, filename: n.media_filename || null } : null },
  metadata: { phone_number_id: n.phone_number_id, execution_id: $execution.id }
};
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { payload, timestamp, idempotency_key: n.event_id, signature_input: timestamp + '.' + JSON.stringify(payload) } };

const n = $('Normalizar evento WhatsApp').item.json;
const registration = $('Painel - Registrar mensagem recebida').item.json;
const timestamp = Math.floor(Date.now() / 1000).toString();
const schemaVersion = '1.0';
const signatureInput = timestamp + '.' + schemaVersion + '.' + n.event_id + '.' + ($json.media_sha256 ?? '');
return { json: { schema_version: schemaVersion, conversation_id: registration.conversation_id, event_id: n.event_id, timestamp, media_sha256: $json.media_sha256 ?? '', signature_input: signatureInput, filename: n.media_filename || (n.event_id + '.bin'), mime_type: $('WhatsApp - Obter URL da mídia').item.json.mime_type ?? n.media_mime_type }, binary: $binary };

const n = $json;
const payload = { schema_version: '1.0', event_id: n.event_id + ':' + n.status, event_type: n.status === 'failed' ? 'message.failed' : 'message.' + n.status, occurred_at: n.occurred_at, external_message_id: n.event_id, recipient: n.from, status: n.status };
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { payload, timestamp, idempotency_key: payload.event_id, signature_input: timestamp + '.' + JSON.stringify(payload) } };

const registration = $('Painel - Registrar mensagem recebida').item.json;
const inbound = $('Normalizar evento WhatsApp').item.json;
const payload = { schema_version: '1.0', revision: registration.revision, worker_id: $execution.id, last_event_id: inbound.event_id };
