const rules = $('Carregar regras de qualificação').all().map(i => ({ segment: i.json.segment, field_key: i.json.field_key, question: i.json.question, required: i.json.required, sequence: i.json.sequence, notes: i.json.notes }));
const claim = $('Painel - Reivindicar rodada da IA').item.json;
const inbound = $('Normalizar evento WhatsApp').item.json;
const waitItem = $('Aguardar agrupamento de mensagens').item.json;
