const value = $json.output ?? $json;
const allowedReasons = ['briefing_complete','human_requested','negotiation','complaint','urgency','low_confidence','unsupported'];
const confidence = Math.max(0, Math.min(1, Number(value.confidence ?? 0)));
const mustHandoff = Boolean(value.handoff_required) || confidence < 0.65;
return { json: {
  reply_text: String(value.reply_text ?? 'Vou encaminhar seu atendimento para nossa equipe.'),
  intent: ['faq','quote_interest','order_status','complaint','other'].includes(value.intent) ? value.intent : 'other',
  segment: ['uniform','event_abada','sport','own_brand','unknown'].includes(value.segment) ? value.segment : 'unknown',
  lead_patch: value.lead_patch && typeof value.lead_patch === 'object' ? value.lead_patch : {},
  missing_fields: Array.isArray(value.missing_fields) ? value.missing_fields : [],
  handoff_required: mustHandoff,
  handoff_reason: mustHandoff ? (allowedReasons.includes(value.handoff_reason) ? value.handoff_reason : 'low_confidence') : null,
  confidence,
  reasoning: String(value.reasoning ?? '').slice(0, 300),
  conversation_id: $('Montar contexto do agente').item.json.conversation_id,
  wa_id: $('Montar contexto do agente').item.json.wa_id,
  phone_number_id: $('Montar contexto do agente').item.json.phone_number_id
} };

const decision = $('Normalizar decisão da IA').item.json;
const messageId = $json.messages?.[0]?.id ?? ('out-' + $execution.id);
const eventType = decision.handoff_required ? 'handoff.requested' : 'message.sent';
const payload = { schema_version: '1.0', event_id: messageId, event_type: eventType, occurred_at: new Date().toISOString(), conversation_id: decision.conversation_id,
  message: { external_id: messageId, sender_type: 'ai', type: 'text', text: decision.reply_text },
  lead_patch: decision.lead_patch, classification: { intent: decision.intent, segment: decision.segment, confidence: decision.confidence, reasoning: decision.reasoning },
  handoff: decision.handoff_required ? { reason: decision.handoff_reason, mode: 'handoff_pending', missing_fields: decision.missing_fields } : null };
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { payload, timestamp, idempotency_key: messageId + ':event', signature_input: timestamp + '.' + JSON.stringify(payload) } };

const headers = $json.headers ?? {};
const timestamp = String(headers['x-silmer-timestamp'] ?? '');
const providedSignature = String(headers['x-silmer-signature'] ?? '');
const idempotencyKey = String(headers['idempotency-key'] ?? '');
let raw = '';
if ($binary?.data?.data) raw = Buffer.from($binary.data.data, 'base64').toString('utf8');
else raw = JSON.stringify($json.body ?? {});
let payload = {};
let parseValid = true;
try { payload = JSON.parse(raw); } catch (error) { parseValid = false; }
const timestampNumber = Number(timestamp);
const timestampValid = Number.isFinite(timestampNumber) && Math.abs(Math.floor(Date.now() / 1000) - timestampNumber) <= 300;
const schemaValid = payload.schema_version === '1.0';
const idempotencyValid = Boolean(payload.command_id) && idempotencyKey === payload.command_id;
return { json: { payload, raw, timestamp, provided_signature: providedSignature, idempotency_key: idempotencyKey, timestamp_valid: timestampValid, parse_valid: parseValid, schema_valid: schemaValid, idempotency_valid: idempotencyValid, signature_input: timestamp + '.' + raw } };

const execution = $json.execution ?? {};
const error = execution.error ?? $json.error ?? {};
return { json: { event_id: 'failure:' + (execution.id ?? $execution.id), conversation_id: '', stage: execution.lastNodeExecuted ?? 'workflow', error_code: error.name ?? 'WORKFLOW_ERROR', error_message: String(error.message ?? 'Erro não identificado').slice(0, 2000), payload_excerpt: JSON.stringify({ workflow: $json.workflow, execution_id: execution.id }).slice(0, 1000), retry_count: 0, created_at: new Date().toISOString(), resolved: false, resolved_at: null } };

const mime = String($json.mime_type ?? '').toLowerCase();
const size = Number($json.file_size ?? 0);
const imageTypes = ['image/jpeg','image/png','image/webp'];
const audioTypes = ['audio/aac','audio/amr','audio/mpeg','audio/mp4','audio/ogg','audio/opus'];
const videoTypes = ['video/mp4','video/3gpp'];
const documentTypes = ['application/pdf','text/plain','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'];
const allowedType = imageTypes.includes(mime) || audioTypes.includes(mime) || videoTypes.includes(mime) || documentTypes.includes(mime);
const defaultLimit = imageTypes.includes(mime) ? 5 * 1024 * 1024 : (audioTypes.includes(mime) || videoTypes.includes(mime)) ? 16 * 1024 * 1024 : 100 * 1024 * 1024;
const panelLimit = Number($env.SILMER_MAX_ATTACHMENT_BYTES ?? defaultLimit);
const effectiveLimit = Math.min(defaultLimit, Number.isFinite(panelLimit) && panelLimit > 0 ? panelLimit : defaultLimit);
const mediaAllowed = allowedType && size > 0 && size <= effectiveLimit;
return { json: { ...$json, media_allowed: mediaAllowed, media_rejection_reason: !allowedType ? 'unsupported_mime_type' : size <= 0 ? 'invalid_file_size' : size > effectiveLimit ? 'file_too_large' : null, effective_limit_bytes: effectiveLimit } };

const claim = $('Painel - Reivindicar rodada da IA').item.json;
const inbound = $('Normalizar evento WhatsApp').item.json;
return { json: {
  conversation_id: claim.conversation_id,
  wa_id: inbound.from,
  phone_number_id: inbound.phone_number_id,
  reply_text: 'Tive uma dificuldade para continuar seu atendimento agora. Vou encaminhar sua conversa para a equipe da Silmer, que seguirá com você assim que possível.',
  handoff_required: true,
  handoff_reason: 'low_confidence',
  error_summary: String($json.error?.message ?? $json.message ?? 'Falha do agente').slice(0, 300)
} };

const fallback = $('Preparar fallback seguro da IA').item.json;
const messageId = $json.messages?.[0]?.id ?? ('fallback-' + $execution.id);
const payload = { schema_version: '1.0', event_id: messageId, event_type: 'handoff.requested', occurred_at: new Date().toISOString(), conversation_id: fallback.conversation_id,
  message: { external_id: messageId, sender_type: 'ai', type: 'text', text: fallback.reply_text },
  lead_patch: {}, classification: { intent: 'other', segment: 'unknown', confidence: 0, reasoning: fallback.error_summary },
  handoff: { reason: 'low_confidence', mode: 'handoff_pending', missing_fields: [] } };
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { payload, timestamp, idempotency_key: messageId + ':event', signature_input: timestamp + '.' + JSON.stringify(payload) } };

const failure = $('Normalizar falha').item.json;
const payload = { schema_version: '1.0', event_id: failure.event_id + ':panel', event_type: 'workflow.failed', occurred_at: failure.created_at, conversation_id: failure.conversation_id || null,
  failure: { stage: failure.stage, code: failure.error_code, message: failure.error_message, retry_count: failure.retry_count } };
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { payload, timestamp, idempotency_key: payload.event_id, signature_input: timestamp + '.' + JSON.stringify(payload) } };

const command = $('Decodificar comando do painel').item.json.payload;
const messageId = $json.messages?.[0]?.id ?? ('human-' + command.command_id);
const payload = { schema_version: '1.0', event_id: messageId, event_type: 'message.sent', occurred_at: new Date().toISOString(), conversation_id: command.conversation_id,
  command_id: command.command_id, actor: command.actor ?? null,
  message: { external_id: messageId, sender_type: 'human', type: command.message?.type ?? 'text', text: command.message?.text ?? '', media_url: command.message?.media_url ?? null } };
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { payload, timestamp, idempotency_key: command.command_id + ':message.sent', signature_input: timestamp + '.' + JSON.stringify(payload) } };
